```python
import math
import random
from dataclasses import dataclass


@dataclass
class Node:
    key: tuple[int, str]
    value: str
    left: "Node | None" = None
    right: "Node | None" = None
    height: int = 1


def height(node: Node | None) -> int:
    return 0 if node is None else node.height


def refresh(node: Node) -> None:
    node.height = 1 + max(height(node.left), height(node.right))


def rotate_left(root: Node) -> Node:
    pivot = root.right
    assert pivot is not None
    middle = pivot.left
    pivot.left = root
    root.right = middle
    refresh(root)
    refresh(pivot)
    return pivot


def rotate_right(root: Node) -> Node:
    pivot = root.left
    assert pivot is not None
    middle = pivot.right
    pivot.right = root
    root.left = middle
    refresh(root)
    refresh(pivot)
    return pivot


def rebalance(root: Node) -> Node:
    refresh(root)
    balance = height(root.left) - height(root.right)

    if balance > 1:
        assert root.left is not None
        if height(root.left.left) < height(root.left.right):
            root.left = rotate_left(root.left)
        return rotate_right(root)

    if balance < -1:
        assert root.right is not None
        if height(root.right.right) < height(root.right.left):
            root.right = rotate_right(root.right)
        return rotate_left(root)

    return root


class AVLIndex:
    def __init__(self):
        self.root = None

    def put(self, key: tuple[int, str], value: str) -> None:
        def insert(node):
            if node is None:
                return Node(key, value)
            if key == node.key:
                node.value = value
                return node
            if key < node.key:
                node.left = insert(node.left)
            else:
                node.right = insert(node.right)
            return rebalance(node)

        self.root = insert(self.root)

    def get(self, key: tuple[int, str]):
        node = self.root
        while node is not None:
            if key == node.key:
                return node.value
            node = node.left if key < node.key else node.right
        return None

    def between(self, start: tuple[int, str], stop: tuple[int, str]):
        result = []

        def visit(node):
            if node is None:
                return
            if node.key >= start:
                visit(node.left)
            if start <= node.key < stop:
                result.append((node.key, node.value))
            if node.key < stop:
                visit(node.right)

        visit(self.root)
        return result


def assert_valid(node, low=None, high=None) -> int:
    if node is None:
        return 0
    assert low is None or low < node.key
    assert high is None or node.key < high
    left_height = assert_valid(node.left, low, node.key)
    right_height = assert_valid(node.right, node.key, high)
    assert abs(left_height - right_height) <= 1
    assert node.height == 1 + max(left_height, right_height)
    return node.height


def root_after(keys):
    index = AVLIndex()
    for key in keys:
        index.put((key, str(key)), "owner")
    assert_valid(index.root)
    return index.root.key[0]


def demo() -> None:
    assert root_after([30, 20, 10]) == 20  # LL
    assert root_after([10, 20, 30]) == 20  # RR
    assert root_after([30, 10, 20]) == 20  # LR
    assert root_after([10, 30, 20]) == 20  # RL

    index = AVLIndex()
    rows = [(timestamp, f"lease-{timestamp:03d}") for timestamp in range(1_000, 1_200)]
    random.Random(7).shuffle(rows)
    for timestamp, lease_id in rows:
        index.put((timestamp, lease_id), f"worker-{timestamp % 5}")
    index.put((1_050, "lease-1050"), "renewed-worker")

    tree_height = assert_valid(index.root)
    assert tree_height <= math.ceil(1.45 * math.log2(len(rows) + 2))
    assert index.get((1_050, "lease-1050")) == "renewed-worker"
    expired = index.between((1_040, ""), (1_045, ""))
    assert [key[0] for key, _ in expired] == [1_040, 1_041, 1_042, 1_043, 1_044]
    print("PASS height=", tree_height, "expired=", len(expired))


if __name__ == "__main__":
    demo()
```

Two concrete uses are a coordinator that looks up leases and scans leases expiring in a time window, and a scheduler that looks up jobs and scans jobs due soon. Strict AVL balance keeps tree height O(log n), making the maximum number of comparisons for lookup predictable. Durable indexes usually use page-oriented B-trees because their high fan-out puts many keys in each storage page, requiring far fewer SSD or disk page reads than a binary AVL tree.

For n stored keys and k reported keys: `get` is O(log n) worst-case time and O(1) auxiliary space; `put`, including rebalancing, is O(log n) time and O(log n) auxiliary space for recursive insertion; and `between` is O(log n + k) time and O(log n) auxiliary space for traversal. Its returned list uses O(k) storage separately.

