from pathlib import Path

from rocksdict import Options, Rdict, WriteBatch


def open_catalog(path: Path) -> Rdict:
    return Rdict(str(path), Options(raw_mode=True))


def write_catalog(db: Rdict, rows: list[tuple[str, str]]) -> None:
    batch = WriteBatch(raw_mode=True)
    for sku, value in rows:
        batch.put(sku.encode("utf-8"), value.encode("utf-8"))
    db.write(batch)
    db.flush(wait=True)


def find_sku(db: Rdict, sku: str) -> str | None:
    value = db.get(sku.encode("utf-8"))
    return None if value is None else value.decode("utf-8")


def scan_skus(db: Rdict, start: str, stop: str) -> list[tuple[str, str]]:
    start_key = start.encode("utf-8")
    stop_key = stop.encode("utf-8")
    iterator = db.iter()
    iterator.seek(start_key)
    rows = []
    while iterator.valid():
        key = iterator.key()
        if key >= stop_key:
            break
        rows.append((key.decode("utf-8"), iterator.value().decode("utf-8")))
        iterator.next()
    return rows
```

A native write batch applies the encoded puts atomically to RocksDB's memtable, and `flush(wait=True)` waits for that mutable memtable to be written as an immutable SST file. A later update writes a newer version through the memtable and subsequent SST files; reads resolve the newest version without modifying an existing SST in place.

