public static Alignment align(String source, String target) {
    int[][] d = new int[source.length() + 1][target.length() + 1];
    for (int i = 0; i <= source.length(); i++) d[i][0] = i;
    for (int j = 0; j <= target.length(); j++) d[0][j] = j;
    for (int i = 1; i <= source.length(); i++) {
        for (int j = 1; j <= target.length(); j++) {
            int best = d[i - 1][j - 1]
                    + (source.charAt(i - 1) == target.charAt(j - 1) ? 0 : 1);
            best = Math.min(best, d[i - 1][j] + 1);
            best = Math.min(best, d[i][j - 1] + 1);
            if (i > 1 && j > 1 && source.charAt(i - 1) == target.charAt(j - 2)
                    && source.charAt(i - 2) == target.charAt(j - 1))
                best = Math.min(best, d[i - 2][j - 2] + 1);
            d[i][j] = best;
        }
    }
    List<Edit> reverse = new ArrayList<>();
    for (int i = source.length(), j = target.length(); i > 0 || j > 0;) {
        if (i > 1 && j > 1 && source.charAt(i - 1) == target.charAt(j - 2)
                && source.charAt(i - 2) == target.charAt(j - 1) && d[i][j] == d[i - 2][j - 2] + 1) {
            reverse.add(Edit.TRANSPOSE); i -= 2; j -= 2;
        } else if (i > 0 && j > 0 && d[i][j] == d[i - 1][j - 1]
                + (source.charAt(i - 1) == target.charAt(j - 1) ? 0 : 1)) {
            reverse.add(source.charAt(i - 1) == target.charAt(j - 1) ? Edit.MATCH : Edit.SUBSTITUTE);
            i--; j--;
        } else if (i > 0 && d[i][j] == d[i - 1][j] + 1) {
            reverse.add(Edit.DELETE); i--;
        } else { reverse.add(Edit.INSERT); j--; }
    }
    Collections.reverse(reverse);
    return new Alignment(d[source.length()][target.length()], List.copyOf(reverse));
}

public static List<Hit> search(Directory directory, String text) throws IOException {
    try (StandardAnalyzer analyzer = new StandardAnalyzer();
         DirectoryReader reader = DirectoryReader.open(directory)) {
        BooleanQuery.Builder query = new BooleanQuery.Builder();
        try (TokenStream tokens = analyzer.tokenStream("title", text)) {
            tokens.reset();
            var term = tokens.addAttribute(CharTermAttribute.class);
            while (tokens.incrementToken())
                query.add(new FuzzyQuery(new Term("title", term.toString()), 2, 1, 50, true),
                          BooleanClause.Occur.MUST);
            tokens.end();
        }
        BooleanQuery built = query.build();
        if (built.clauses().isEmpty()) return List.of();
        IndexSearcher searcher = new IndexSearcher(reader);
        List<Hit> hits = new ArrayList<>();
        for (ScoreDoc scoreDoc : searcher.search(built, 50).scoreDocs) {
            Document doc = searcher.storedFields().document(scoreDoc.doc);
            hits.add(new Hit(doc.get("id"), doc.get("title"), scoreDoc.score));
        }
        return List.copyOf(hits);
    }
}
